 if(el.dataset.coordinate){const o=obj(),r=room();if(!o||o.lock==='fixed')return;const v=Number(el.value);if(!Number.isFinite(v)){render();return}const [x,y]=constrain(r,o,el.dataset.coordinate==='x'?v:o.x,el.dataset.coordinate==='y'?v:o.y);commit('调整对象坐标',()=>{o.x=x;o.y=y});return}
 if(el.dataset.setting){const o=obj();if(!o)return;const key=el.dataset.setting,value=el.value;if(key==='target'){const r=data.rooms.find(x=>x.id===value),spawns=r?spawnIds(r):[];if(!spawns.length){toast('目标场景没有入口，请先添加 start 入口。');render();return}commit('修改出口目标',()=>{o.target=value;o.targetSpawn=spawns.includes('start')?'start':spawns[0];o.changed=true});return}if(key==='targetSpawn'&&!spawnIds(data.rooms.find(x=>x.id===o.target)).includes(value)){render();return}commit(key==='lock'?'修改对象自由度':'修改出口草案',()=>{o[key]=value;if(key!=='lock')o.changed=true});return}
